// Enhance the SVG animation generated by Platane/snk without replacing live contribution data.
// This file uses only built-in Node.js APIs and runs after the snk GitHub Action.
import { readFileSync, writeFileSync } from "node:fs";

const THEMES = {
  "dark": {
    "panelA": "#0B1220",
    "panelB": "#101C2E",
    "border": "#2A3B50",
    "header": "#E5F6FF",
    "muted": "#93ADC2",
    "accent": "#65E4D6",
    "line": "#264055",
    "eyes": "#0B1220",
    "segments": [
      "#EBFAFF",
      "#C5BBFF",
      "#A58BFF",
      "#7C73E8"
    ],
    "glow": "#927CFF"
  },
  "light": {
    "panelA": "#FCFEFF",
    "panelB": "#EAF2F8",
    "border": "#CDDDE9",
    "header": "#213548",
    "muted": "#5C778D",
    "accent": "#148F91",
    "line": "#CCDDE8",
    "eyes": "#152336",
    "segments": [
      "#FBFFFF",
      "#B2FAEA",
      "#8BD9E4",
      "#8068DE"
    ],
    "glow": "#7661DE"
  }
};

export function decorateSvg(svg, theme) {
  const c = THEMES[theme];
  if (!c) throw new Error("Invalid theme: " + theme);
  if (svg.includes('id="profile-snake-skin"')) return svg;
  if (!svg.startsWith("<svg ") || !svg.includes("</style>") || !svg.includes('class="s s0"')) {
    throw new Error("Unsupported Platane/snk SVG layout");
  }
  svg = svg.replace(/^<svg\b[^>]*>/, match =>
    match.replace(/viewBox="[^"]+"/, 'viewBox="-20 -64 888 252"')
      .replace(/width="[^"]+"/, 'width="888"')
      .replace(/height="[^"]+"/, 'height="252"'));
  const defs = `<defs id="profile-snake-skin"><linearGradient id="snake-panel" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="${c.panelA}"/><stop offset="100%" stop-color="${c.panelB}"/></linearGradient><linearGradient id="snake-accent" x1="0" y1="0" x2="1" y2="0"><stop stop-color="${c.accent}"/><stop offset="100%" stop-color="${c.glow}"/></linearGradient></defs>`;
  svg = svg.replace(/(<svg\b[^>]*>)/, "$1" + defs);
  svg = svg.replace(/<rect class="c([^"]*)"([^>]*?)\/>/g, (_, classes, attrs) =>
    `<rect class="c${classes}"${attrs.replace(/rx="2"/, 'rx="3.2"').replace(/ry="2"/, 'ry="3.2"')}/>`);
  const css = `
    .s.s0{fill:${c.segments[0]};filter:drop-shadow(0 0 4px ${c.glow});}
    .s.s1{fill:${c.segments[1]};filter:drop-shadow(0 0 2px ${c.glow});}
    .s.s2{fill:${c.segments[2]};}
    .s.s3{fill:${c.segments[3]};}
    .snake-status{animation:snake-pulse 2.8s ease-in-out infinite;transform-origin:center}
    @keyframes snake-pulse{0%,100%{opacity:0.5}50%{opacity:1}}
  `.replace(/\s{2,}/g, " ");
  svg = svg.replace("</style>", css + "</style>");
  const decorations = `<rect x="-19" y="-63" width="886" height="250" rx="18" fill="url(#snake-panel)" stroke="${c.border}" stroke-width="1.4"/><rect x="-18" y="-62" width="884" height="2" rx="1" fill="url(#snake-accent)" opacity="0.8"/><rect x="0" y="-47" width="3" height="14" rx="1.5" fill="url(#snake-accent)"/><text x="15" y="-36" fill="${c.header}" font-family="Verdana,Arial,sans-serif" font-size="11.5" font-weight="700" letter-spacing="2">CONTRIBUTION FLOW</text><circle class="snake-status" cx="702" cy="-40" r="3.5" fill="${c.accent}"/><text x="848" y="-36" fill="${c.muted}" font-family="Verdana,Arial,sans-serif" font-size="10" text-anchor="end" letter-spacing="1.2">ONMAYNEC / GITHUB</text><path d="M0 -25.5H848" stroke="${c.line}" stroke-width="1" opacity="0.75"/><path d="M0 133.5H848" stroke="${c.line}" stroke-width="1" opacity="0.65"/>`;
  svg = svg.replace("</style>", "</style>" + decorations);
  // The moving head's eyes share its original keyframe animation.
  svg = svg.replace(/<rect class="s s0"([^>]*?)\/>/, (_, attrs) =>
    `<g class="s s0"><rect${attrs}/><circle cx="10.2" cy="5.2" r="1.45" fill="${c.eyes}"/><circle cx="10.2" cy="10.2" r="1.45" fill="${c.eyes}"/></g>`);
  const footer = `<text x="0" y="174" fill="${c.muted}" font-family="Verdana,Arial,sans-serif" font-size="9" letter-spacing="1.5">REAL GITHUB CONTRIBUTIONS</text><text x="848" y="174" fill="${c.muted}" font-family="Verdana,Arial,sans-serif" font-size="9" text-anchor="end" letter-spacing="1.5">UPDATED DAILY</text>`;
  svg = svg.replace("</svg>", footer + "</svg>");
  if (!svg.includes('<g class="s s0">') || !svg.includes("animation-name:s0") || !svg.includes("profile-snake-skin")) {
    throw new Error("Snake animation validation failed");
  }
  return svg;
}

if (process.argv[1]?.endsWith("decorate-snake.mjs")) {
  for (const theme of ["dark", "light"]) {
    const path = `dist/snake-${theme}.svg`;
    const input = readFileSync(path, "utf8");
    const output = decorateSvg(input, theme);
    writeFileSync(path, output, "utf8");
    process.stdout.write(`Enhanced ${path} (${output.length} chars)\n`);
  }
}
